import type { Metadata } from "next";
import { readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { PageHeader } from "@/site/docs/PageHeader";
import { TokenExport } from "@/site/docs/TokenExport";
import { CodeBlock } from "@/components/ui/CodeBlock";

export const metadata: Metadata = { title: "Token Export" };

// Both files are generated by `npm run tokens:build` (runs before every build), so the
// preview and download always match tokens.json.
const file = (name: string) => join(process.cwd(), "public", "downloads", name);
const head = (name: string, lines: number) => readFileSync(file(name), "utf8").split("\n").slice(0, lines).join("\n") + "\n// …";
const size = (name: string) => `${Math.max(1, Math.round(statSync(file(name)).size / 1000))} KB`;

export default function TokenExportPage() {
  return (
    <div>
      <PageHeader
        title="Token Export"
        description="Download the Sitka tokens as W3C DTCG JSON or as Swift. Both files are generated from tokens.json on every build."
      />
      <TokenExport
        previews={{ json: head("sitka-tokens.json", 30), swift: head("SitkaTokens.swift", 60) }}
        sizes={{ json: size("sitka-tokens.json"), swift: size("SitkaTokens.swift") }}
      />

      <section className="mt-10 space-y-3">
        <h2 className="text-[16px] font-semibold text-[rgb(var(--text-primary))]">Swift Package Manager</h2>
        <p className="text-[14px] text-[rgb(var(--text-secondary))]">
          In Xcode choose File › Add Package Dependencies, enter the repository URL, and add the{" "}
          <code className="font-mono text-[12px]">SitkaTokens</code> product. Or in <code className="font-mono text-[12px]">Package.swift</code>:
        </p>
        <CodeBlock
          language="swift"
          filename="Package.swift"
          code={`.package(url: "https://github.com/jsrothwell/Sitka.git", from: "1.13.0")

// target dependencies:
.product(name: "SitkaTokens", package: "Sitka")`}
        />
        <CodeBlock
          language="swift"
          filename="Usage.swift"
          code={`import SitkaTokens

Text("Synced")
    .foregroundStyle(Color.sitka(\\.statusSuccessText))   // follows light/dark
    .padding(SitkaTokens.Spacing.s4)`}
        />
      </section>
    </div>
  );
}
